          "Anggap initial invalid state sebagai precondition yang perlu kamu buktikan sebelum mengubah form.",
          "Reuse locator untuk alert dan Register supaya assertion-nya jelas menceritakan satu state transition.",
          "Setelah mengisi kedua labeled field, buktikan dua efek rule-nya: guidance hilang dan submission tersedia."
        ]
      },
      "htmlContent": "<form id=\"signup\">\n  <div class=\"field\">\n    <label>Email <input type=\"email\" id=\"email\" value=\"bad-email\" /></label>\n    <span class=\"error\" id=\"email-error\" role=\"alert\">Invalid email format</span>\n  </div>\n  <div class=\"field\">\n    <label>Password <input type=\"password\" id=\"password\" placeholder=\"8+ characters\" /></label>\n    <span class=\"hint\">Must be 8+ characters</span>\n  </div>\n  <button id=\"submit\" disabled>Register</button>\n</form>\n<script>\n  document.getElementById('email').addEventListener('input', validate);\n  document.getElementById('password').addEventListener('input', validate);\n  function validate() {\n    const email = document.getElementById('email').value;\n    const pass = document.getElementById('password').value;\n    const valid = email.includes('@') && pass.length >= 8;\n    document.getElementById('submit').disabled = !valid;\n    document.getElementById('email-error').style.display = email.includes('@') ? 'none' : 'block';\n  }\n</script>",
      "starterCode": "import { test, expect } from '@playwright/test';\n\ntest('practice', async ({ page }) => {\n  // TODO 1\n  // TODO 2\n  // TODO 3\n  // TODO 4\n  // TODO 5\n});",
