            "files": {
                "/tests/recommendations.spec.ts": "import { test, expect } from '@playwright/test';\n\ntest('recommendations-recovery', async ({ page }) => {\n  await page.goto('/app/recommendations.html');\n  await page.route('/api/recommendations', async (route) => {\n    await route.fulfill({\n      status: 200,\n      contentType: 'application/json',\n      json: {\n        items: ['Release health dashboard', 'Checkout recovery']\n      }\n    });\n  });\n\n  await page.getByRole('button', { name: 'Load recommendations' }).click();\n  await expect(page.getByRole('list', { name: 'Recommended checks' })).toBeVisible();\n});",
                "/app/recommendations.html": "<main class='min-h-screen max-w-2xl mx-auto p-8'>\n  <h1 class='text-2xl font-bold'>Recommendations</h1>\n  <p id='request-state' role='status' class='mt-4'>Ready to load recommendations</p>\n  <p id='error-message' role='alert' class='error-text mt-4' hidden style='display:none'>Recommendations are temporarily unavailable. Try again.</p>\n  <button id='load-button' type='button' class='button button-primary mt-4'>Load recommendations</button>\n  <button id='retry-button' type='button' class='button button-primary mt-4' hidden style='display:none'>Retry</button>\n  <section id='recommendation-results' class='card mt-6 p-6' aria-labelledby='results-heading' hidden>\n    <h2 id='results-heading' class='text-lg font-semibold'>Recommended checks</h2>\n    <ul id='recommendations' aria-label='Recommended checks' class='mt-3 list-disc pl-5'></ul>\n  </section>\n</main>\n<script>\n  (function() {\n    const state = document.getElementById('request-state');\n    const errorMessage = document.getElementById('error-message');\n    const loadButton = document.getElementById('load-button');\n    const retryButton = document.getElementById('retry-button');\n    const results = document.getElementById('recommendation-results');\n    const recommendations = document.getElementById('recommendations');\n\n    async function loadRecommendations() {\n      state.hidden = false;\n      state.style.display = 'block';\n      state.textContent = 'Loading recommendations...';\n      errorMessage.hidden = true;\n      errorMessage.style.display = 'none';\n      loadButton.hidden = true;\n      loadButton.style.display = 'none';\n      retryButton.hidden = true;\n      retryButton.style.display = 'none';\n      results.hidden = true;\n      results.style.display = 'none';\n\n      try {\n        const response = await window.fetch('/api/recommendations');\n        if (response.status === 503) throw new Error('temporary-service-outage');\n        if (response.status !== 200) throw new Error('unexpected-response');\n        const payload = await response.json();\n        if (!payload || !Array.isArray(payload.items)) throw new Error('invalid-response');\n\n        recommendations.innerHTML = payload.items.map((item) => '<li>' + item + '</li>').join('');\n        state.textContent = 'Recommendations loaded';\n        results.hidden = false;\n        results.style.display = 'block';\n      } catch (error) {\n        state.hidden = true;\n        state.style.display = 'none';\n        results.hidden = true;\n        errorMessage.textContent = error && error.message === 'temporary-service-outage'\n          ? 'Recommendations are temporarily unavailable. Try again.'\n          : 'Unable to load recommendations. Please try again.';\n        errorMessage.hidden = false;\n        errorMessage.style.display = 'block';\n        retryButton.hidden = false;\n        retryButton.style.display = 'inline-block';\n      }\n    }\n\n    loadButton.addEventListener('click', loadRecommendations);\n    retryButton.addEventListener('click', loadRecommendations);\n  })();\n</script>"
            },
