      "solution": "interface TestRunSummary {\n  name: string;\n  passed: number;\n  failed: number;\n}\n\nconst loginRun: TestRunSummary = {\n  name: \"Login flow\",\n  passed: 8,\n  failed: 2,\n};\nconst total = loginRun.passed + loginRun.failed;\nconst result = `${loginRun.name}: ${loginRun.passed}/${total} passed`;",
