          "Akses elemen tuple menggunakan indeks barbasis nol seperti `pos[0]` dan `pos[1]` setelah mendefinisikan `type Coordinate = [number, number]`."
        ]
      },
      "htmlContent": "<div class=\"geo-tracker\">\n  <h3>GPS Tracker</h3>\n  <div id=\"location\">Searching signal...</div>\n</div>",
      "starterCode": "// 1. Define type Coordinate = [number, number]\n// Your code here\n\n// 2. Initialize pos: Coordinate = [10, 20]\n// Your code here\n\n// 3. result = pos[0] + pos[1]\n// Your code here",
      "testCases": [
        {
          "description": "Returns the sum of tuple elements",
          "expectedOutput": "30",
          "isHidden": false
        }
      ],
      "solution": "type Coordinate = [number, number];\nconst pos: Coordinate = [10, 20];\nconst result = pos[0] + pos[1];",
      "tags": ["typescript", "type-aliases", "tuples"]
    },
